using System;using System.IO;using System.Linq;using System.Drawing;using System.Reflection;using System.Diagnostics;using System.Windows.Forms;using Musikbox;using MusikboxTests;
class Workspace63 {
 static int count;static void Check(bool ok,string label){if(!ok)throw new Exception(label);count++;Console.WriteLine("PASS "+label);}
 static object Field(object o,string n){return o.GetType().GetField(n,BindingFlags.NonPublic|BindingFlags.Instance).GetValue(o);}
 static object Call(object o,string n,params object[] a){return o.GetType().GetMethod(n,BindingFlags.NonPublic|BindingFlags.Instance).Invoke(o,a);}
 static void Wait(Func<bool> condition){var watch=Stopwatch.StartNew();while(watch.ElapsedMilliseconds<6000){Application.DoEvents();if(watch.ElapsedMilliseconds>250&&condition())return;System.Threading.Thread.Sleep(10);}throw new Exception("UI-Zeitlimit");}
 [STAThread] static int Main(){Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);string root=Path.Combine(Path.GetTempPath(),"Musikbox-Workspace63-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);try{using(var v=new MainView(Path.Combine(root,"layout.json"))){var c=new Controller(v,Path.Combine(root,"backups"),new Playback(new PlaybackTestDevice()));var p=new Project();p.Folders.Add(new BoxFolder{Name="000 Test",Songs=Enumerable.Range(0,80).Select(i=>new Song{Source=Path.Combine(root,i+".mp3"),Artist="AC/DC",Title="Thunderstruck "+i,Album="Test"}).ToList()});Call(c,"ReplaceProject",p,null,true);v.Show();v.WindowState=FormWindowState.Normal;Application.DoEvents();v.Songs.ClearSelection();v.Songs.Rows[3].Selected=true;v.Songs.Rows[4].Selected=true;var selected=v.Songs.SelectedRows.Cast<DataGridViewRow>().Select(r=>r.Tag).ToArray();
 foreach(var size in new[]{new Size(1000,680),new Size(1250,800),new Size(1700,1000)}){v.ClientSize=size;foreach(string page in new[]{"Bibliothek","Tag-Editor","Konvertierung","MP3Gain","fre:ac","FFmpeg","Video-Audio-Import","Coversuche","Coverbearbeitung","Covergestaltung","Cover zuweisen / exportieren","Einstellungen","Export","Statistiken","Wiedergabelisten"}){Call(c,"OpenStudioModule",page);Application.DoEvents();var table=(Control)Field(v,"studioLibrary");var metadata=(Control)Field(v,"studioRight");bool full=new[]{"Einstellungen","Export","Statistiken","Wiedergabelisten"}.Contains(page);Check(table.Visible==!full,page+" Titellistensichtbarkeit");Check(metadata.Visible==!full,page+" Metadatenleiste");Check(v.ModuleHost.Controls.Count<=1,page+" ein Modul");Check(v.Songs.Rows.Count==80,page+" Zeilen erhalten");Check(v.Songs.SelectedRows.Cast<DataGridViewRow>().Select(r=>r.Tag).OrderBy(x=>Array.IndexOf(selected,x)).SequenceEqual(selected),page+" Auswahl erhalten");if(!full&&page!="Bibliothek")Check(!table.Bounds.IntersectsWith(v.ModuleHost.Bounds),page+" Arbeitsbereiche überlappen nicht");var before=table.Bounds;Call(v,"RefreshStudioNow");Check(table.Bounds==before,page+" wiederholtes Layout bleibt stabil");}}
 Call(c,"OpenStudioModule","MP3Gain");v.SearchBox.Text="ACDC Thunder";Wait(()=>v.Songs.Rows.Count==80);Check(v.ModuleHost.Visible,"Suche bleibt im Werkzeug");v.SearchBox.Text="";Wait(()=>v.Songs.Rows.Count==80);
 v.Close();}Console.WriteLine("BESTANDEN: "+count+" Windows-UI-Prüfungen");return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}finally{try{Directory.Delete(root,true);}catch{}}}
}
